\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{conjecture}[theorem]{Conjecture}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\Q}{\mathbb{Q}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\PK}{P_K}
\newcommand{\Pgauss}{P_{\Q(i)}}
\newcommand{\Norm}{N}
\newcommand{\gterm}{\operatorname{gaussTerm}}
\DeclareMathOperator{\Real}{Re}

\title{A Two-Sided Abscissa Bracket for the Prime-Ideal Zeta Function of an
Imaginary Quadratic Field, with a Conjectural Natural Boundary}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We study the prime-ideal zeta function $\PK(s) = \sum_{\mathfrak{p}}
\Norm(\mathfrak{p})^{-s}$ of an imaginary quadratic field $K$ of class number
one, taking the Gaussian field $K = \Q(i)$ as the running model. Using the
splitting law of rational primes in $\Z[i]$ (governed by $p \bmod 4$), we
organize $\PK$ as an explicit Dirichlet series over the rational primes and prove
an unconditional two-sided bracket on its abscissa of convergence: the series
converges absolutely for every $s > 1$ and diverges for every $s \le \tfrac12$.
The ceiling follows from a pointwise comparison $\gterm(s,p) \le 2\,p^{-s}$
against twice the rational prime zeta function; the floor follows from a pointwise
comparison $\gterm(s,p) \ge p^{-2s}$ using the inert primes of norm $p^2$. We
further establish strict positivity in the region of convergence and a
quantitative bridge $\Pgauss(s) \le 2P(s)$. We then formulate three conjectures
beyond the elementary estimates: that the sharp abscissa is exactly $1$, that the
analytic continuation of $\PK$ admits the imaginary axis $\Real(s) = 0$ as a
natural boundary, and that consequently no zeta-style regularization of the
``product of all prime ideals'' can exist.
\end{abstract}

\section{Introduction}

\subsection{Regularizing divergent sums over primes}
The Riemann zeta function $\zeta(s) = \sum_{n \ge 1} n^{-s}$ converges only for
$\Real(s) > 1$, yet its analytic continuation assigns finite values such as
$\zeta(-1) = -\tfrac{1}{12}$ where the series diverges. This regularization
underlies many computations in mathematical physics. A recurring question is
which divergent sums can be regularized this way.

The \emph{prime zeta function} $P(s) = \sum_{p} p^{-s}$ is the prime-supported
analogue. It has abscissa of convergence exactly $1$; the value at $s = -1$ never
arises from the series itself, only from continuation. Moreover $P$ possesses the
line $\Real(s) = 0$ as a natural boundary (Landau--Walfisz).

\subsection{The number-field generalization}
For a number field $K$ with ring of integers $\mathcal{O}_K$,
\[
  \PK(s) = \sum_{\mathfrak{p}} \Norm(\mathfrak{p})^{-s},
\]
the sum over nonzero prime ideals with $\Norm(\mathfrak{p}) =
|\mathcal{O}_K/\mathfrak{p}|$. We focus on imaginary quadratic fields of class
number one and take $K = \Q(i)$ (discriminant $-4$, class number $1$).

\section{The Gaussian splitting law and the series model}

The factorization of a rational prime $p$ in $\Z[i]$ depends only on $p \bmod 4$:
\begin{itemize}
  \item $p = 2$ (ramified): $2 = -i(1+i)^2$, one prime ideal of norm $2$;
  \item $p \equiv 1 \pmod 4$ (split): two conjugate prime ideals, each of norm $p$;
  \item $p \equiv 3 \pmod 4$ (inert): one prime ideal of norm $p^2$.
\end{itemize}

\begin{definition}[Gaussian term]
For $s \in \R$ and a rational prime $p$,
\[
  \gterm(s,p) =
  \begin{cases}
    2^{-s}, & p = 2,\\
    2\,p^{-s}, & p \equiv 1 \pmod 4,\\
    p^{-2s}, & p \equiv 3 \pmod 4.
  \end{cases}
\]
\end{definition}

\begin{definition}[Gaussian prime-ideal zeta]
$\Pgauss(s) = \sum_{p} \gterm(s,p)$, summed over rational primes.
\end{definition}

Every prime ideal of $\Z[i]$ lies above a unique rational prime, so this
reorganization equals $\sum_{\mathfrak{p}} \Norm(\mathfrak{p})^{-s}$ exactly.

\begin{proposition}[Abscissa of the rational prime zeta]
$P(s) = \sum_p p^{-s}$ converges absolutely if and only if $s > 1$.
\end{proposition}
\begin{proof}[Proof sketch]
Summability of $p \mapsto p^{-s} = p^{r}$ over primes holds iff $r = -s < -1$,
i.e. $s > 1$; equivalently $P$ shares the abscissa $1$ of $\sum_n n^{-s}$.
\end{proof}

\section{Pointwise bounds}

\begin{lemma}[Nonnegativity]
For all $s \in \R$ and primes $p$, $0 \le \gterm(s,p)$.
\end{lemma}
\begin{proof}[Proof sketch]
Each branch is a nonnegative constant times a positive real power of a positive
base.
\end{proof}

\begin{lemma}[Upper bound]
For all $s \ge 0$ and primes $p$, $\gterm(s,p) \le 2\,p^{-s}$.
\end{lemma}
\begin{proof}[Proof sketch]
For $p=2$, $2^{-s} \le 2\cdot 2^{-s}$. For $p \equiv 1$, equality. For
$p\equiv 3$, $p^{-2s} \le p^{-s} \le 2 p^{-s}$ since $p \ge 2$ and $-2s \le -s$.
\end{proof}

\begin{lemma}[Lower bound]
For all $s \ge 0$ and primes $p$, $p^{-2s} \le \gterm(s,p)$.
\end{lemma}
\begin{proof}[Proof sketch]
For $p=2$, $2^{-2s}\le 2^{-s}$. For $p\equiv 1$, $p^{-2s}\le p^{-s}\le 2p^{-s}$.
For $p\equiv 3$, equality.
\end{proof}

\section{The unconditional abscissa bracket}

\begin{theorem}[Convergence for $s>1$]
For every $s > 1$, the series $\sum_p \gterm(s,p)$ converges absolutely.
\end{theorem}
\begin{proof}[Proof sketch]
Terms are nonnegative and dominated by $2p^{-s}$; the majorant $2P(s)$ converges
for $s>1$, so comparison applies.
\end{proof}

\begin{theorem}[Divergence for $s \le \tfrac12$]
For every $s$ with $0 \le s \le \tfrac12$, the series $\sum_p \gterm(s,p)$
diverges.
\end{theorem}
\begin{proof}[Proof sketch]
Terms dominate $p^{-2s}$; the minorant $\sum_p p^{-2s} = P(2s)$ diverges for
$2s \le 1$. Convergence of the Gaussian series would force convergence of the
minorant, a contradiction. Divergence is driven by the inert primes alone.
\end{proof}

\begin{corollary}[Abscissa bracket]
The abscissa of convergence $\sigma_c$ of $\Pgauss$ satisfies
$\tfrac12 \le \sigma_c \le 1$. The floor is forced by the inert primes, the
ceiling by the split (and ramified) primes.
\end{corollary}

\section{Positivity and the bridge}

\begin{theorem}[Strict positivity]
For every $s > 1$, $\Pgauss(s) > 0$.
\end{theorem}
\begin{proof}[Proof sketch]
The series converges with nonnegative terms, and the ramified prime $p=2$
contributes the strictly positive term $2^{-s}$.
\end{proof}

\begin{theorem}[Bridge inequality]
For every $s > 1$, $\Pgauss(s) \le 2\,P(s)$.
\end{theorem}
\begin{proof}[Proof sketch]
Both sides converge for $s>1$; sum the termwise bound $\gterm(s,p) \le 2p^{-s}$.
\end{proof}

The constant $2$ is the field degree $[\Q(i):\Q]=2$, the maximal number of prime
ideals above any rational prime, and is optimal.

\section{The general imaginary quadratic model}

For an arbitrary imaginary quadratic field $K$ of class number one, encode the
arithmetic by splitting data: $\deg_1(p) \in \{0,1,2\}$ (degree-one ideals of
norm $p$) and $\mathrm{inert}(p) \in \{0,1\}$ (degree-two ideals of norm $p^2$).

\begin{definition}[General model]
\[
  \PK(s) = \sum_{p} \Big( \deg_1(p)\,p^{-s} + \mathrm{inert}(p)\,p^{-2s} \Big).
\]
\end{definition}

Specializing to $\Q(i)$ recovers the Gaussian term. Since $\deg_1(p)\le 2$ and
$\mathrm{inert}(p)\le 1$, the same two pointwise bounds hold and the bracket
$[\tfrac12,1]$ holds for every such $K$. For $s \le 0$ the inert terms
$p^{-2s} = p^{|2s|}$ grow without bound, exhibiting the regularization
obstruction.

\section{Conjectures}

\begin{conjecture}[Abscissa exactly $1$]
For every imaginary quadratic field $K$ of class number one, $\PK$ converges for
$s>1$ and diverges at $s=1$.
\end{conjecture}
The gap $(\tfrac12,1]$ is controlled by the split primes ($\chi_d(p)=+1$), whose
reciprocal sum diverges by Dirichlet density $\tfrac12$; an Abel summation bridge
from $\Lambda(p)/p$ to $1/p$ over a residue class upgrades the divergence to
$s=1$.

\begin{conjecture}[Natural boundary]
The analytic continuation of $\PK$ admits $\Real(s)=0$ as a natural boundary.
\end{conjecture}
The expansion $\PK(s) = \sum_{k\ge 1} \tfrac{\mu(k)}{k}\log\zeta_K(ks)$ turns each
nontrivial zero $\rho$ of $\zeta_K$ into a singularity at $\rho/k$; these
accumulate densely on $\Real(s)=0$. Class number one gives
$\zeta_K = \zeta \cdot L(\cdot,\chi_d)$, so zeros of both factors contribute.

\begin{conjecture}[No regularized product of all prime ideals]
There is no zeta-style regularized value for the product of all prime ideals of
$K$, since the evaluation point $s=0$ lies on the natural boundary.
\end{conjecture}

\section{Conclusion}
We established an unconditional bracket $[\tfrac12,1]$ for the abscissa of
$\Pgauss$, strict positivity, and a factor-of-two bridge to the rational prime
zeta, and abstracted these to all imaginary quadratic fields of class number one.
The floor is the inert contribution; the ceiling and conjectural natural boundary
are the split contribution and the zeros of $\zeta_K$. The bracket isolates the
field-dependent ingredient---positive density of split primes---whose resolution
would yield the sharp abscissa, the natural boundary, and the impossibility of
regularizing the product of all prime ideals.

\end{document}

